on conflict (slug) do update set categorie = excluded.categorie, nom = excluded.nom, editeur = excluded.editeur, resume = excluded.resume,
  duree = excluded.duree, appareils = excluded.appareils, inclus = excluded.inclus, periode = excluded.periode, livraison = excluded.livraison, ordre = excluded.ordre;
